// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIAuditRun) predicate.AIAuditRun {
	return predicate.AIAuditRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIAuditRun) predicate.AIAuditRun {
	return predicate.AIAuditRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIAuditRun) predicate.AIAuditRun {
	return predicate.AIAuditRun(sql.NotPredicates(p))
}
